(()=>{'use strict';const root=document.getElementById('av-services-slider');if(!root)return;const track=root.querySelector('.sv-track'),cards=[...root.querySelectorAll('.sv-card')],prev=root.querySelector('[data-sv-prev]'),next=root.querySelector('[data-sv-next]'),count=root.querySelector('.sv-count');if(!track||!cards.length||!prev||!next||!count)return;let index=0,frame;
const update=()=>{const left=track.getBoundingClientRect().left,padding=parseFloat(getComputedStyle(track).paddingLeft)||0,scroll=track.scrollLeft,width=track.clientWidth,total=track.scrollWidth;let distance=Infinity;cards.forEach((card,i)=>{const delta=Math.abs(card.getBoundingClientRect().left-left-padding);if(delta<distance){distance=delta;index=i}});const label=(index+1)+' / '+cards.length;if(count.textContent!==label)count.textContent=label;prev.disabled=scroll<2;next.disabled=scroll+width>=total-2};
const schedule=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(update)};
const go=dir=>{update();const card=cards[Math.max(0,Math.min(cards.length-1,index+dir))];track.scrollTo({left:card.offsetLeft-track.offsetLeft-(parseFloat(getComputedStyle(track).paddingLeft)||0),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
prev.addEventListener('click',()=>go(-1));next.addEventListener('click',()=>go(1));track.addEventListener('scroll',schedule,{passive:true});track.addEventListener('keydown',event=>{if(event.target!==track)return;if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();go(event.key==='ArrowRight'?1:-1)}});window.addEventListener('resize',schedule,{passive:true});
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){schedule();observer.disconnect()}},{rootMargin:'200px'});observer.observe(root)}else schedule();
})();